  wl: { n: 'White Liquor', c: '#e0e4d8', f: 'NaOH and Na₂S in water, about 80°C. The sulfide speeds up delignification and protects the cellulose', cp: 3.6, t: 80, corr: 0.6, ck: 'alk' },
  bl: { n: 'Black Liquor', c: '#2a2218', f: 'Dissolved lignin and spent sodium salts, about 90°C. Concentrated, it burns like heavy oil', cp: 3.2, t: 90, corr: 0.3, ck: 'alk' },
  gl: { n: 'Green Liquor', c: '#6a8a6a', f: 'Smelt dissolved in water: Na₂CO₃ and Na₂S, tinted green by traces of iron', cp: 3.6, t: 85, corr: 0.4, ck: 'alk' },
  butadiene: { n: 'Butadiene', c: '#d8d0e0', f: 'CH₂=CH-CH=CH₂, a gas with two double bonds. Extracted from the C₄ cut of a steam cracker', gas: true, cp: 1.5, t: 40 },
  benzene: { n: 'Benzene', c: '#e8e4d0', f: 'C₆H₆, the parent aromatic ring. A clear, sweet-smelling liquid that boils at 80°C', cp: 1.7, t: 30 },
  styrene: { n: 'Styrene', c: '#e0dcc8', f: 'C₆H₅CH=CH₂, an oily liquid that slowly polymerises by itself unless kept cool and inhibited', cp: 1.7, t: 25 },
  olefins: { n: 'Linear Olefins', c: '#e0d8b0', f: 'Straight-chain alpha-olefins, mostly C₁₀ to C₁₄, built up from ethylene two carbons at a time', cp: 2.2, t: 40 },
  lab: { n: 'Linear Alkylbenzene', c: '#e8e0b8', f: 'A benzene ring on a straight C₁₂ tail. The straight chain lets bacteria break it down, unlike the branched kind used before 1965', cp: 2.0, t: 40 },
  las: { n: 'Alkylbenzene Sulfonic Acid', c: '#a88a48', f: 'LAS acid: a water-loving sulfonate head on an oily tail. Neutralised, it is the main surfactant in washing powder', cp: 1.8, t: 50, corr: 0.5, ck: 'acid' },
  cyclohexane: { n: 'Cyclohexane', c: '#e8eef0', f: 'C₆H₁₂, benzene with its double bonds filled with hydrogen. A clear solvent that smells like petrol', cp: 1.85, t: 40 },
  ka_oil: { n: 'KA Oil', c: '#d8c890', f: 'Ketone-alcohol oil: cyclohexanone and cyclohexanol mixed, the half-oxidised form of cyclohexane', cp: 1.9, t: 60 },
  n2o: { n: 'Nitrous Oxide', c: '#c0d0e8', f: 'N₂O, laughing gas. Each tonne warms the climate about 270 times as much as a tonne of CO₂', cp: 0.88, t: 40 },
  hmda: { n: 'Hexamethylenediamine', c: '#d0c8e0', f: 'H₂N-(CH₂)₆-NH₂, a six-carbon chain with an amine at each end. Kept molten at about 50°C', cp: 2.2, t: 60, corr: 0.3, ck: 'alk' },
  propylene: { n: 'Propylene', c: '#e0e8d8', f: 'C₃H₆, ethylene with a methyl group. The second biggest product of a cracker', cp: 1.5, t: 30 },
  cumene: { n: 'Cumene', c: '#e8e0c8', f: 'Isopropylbenzene. Almost every molecule of it is made to be split into phenol and acetone', cp: 1.8, t: 40 },
  phenol: { n: 'Phenol', c: '#f0e0e0', f: 'C₆H₅OH, carbolic acid. Kept molten at 50°C; it burns skin and numbs it at the same time', cp: 2.0, t: 50, corr: 0.4, ck: 'acid' },
  acetone: { n: 'Acetone', c: '#e0f0f8', f: '(CH₃)₂CO, the smallest ketone. A solvent that mixes with water and oil alike', cp: 2.2, t: 30 },
  acetic: { n: 'Acetic Acid', c: '#e8ecd8', f: 'CH₃COOH, glacial: pure enough to freeze at 17°C. Vinegar is 5% of it', cp: 2.0, t: 40, corr: 0.6, ck: 'acid' },
  ac2o: { n: 'Acetic Anhydride', c: '#d8e0c8', f: '(CH₃CO)₂O, two acetic acids with the water pulled out. It hands an acetyl group to anything with an OH', cp: 1.8, t: 40, corr: 0.6, ck: 'acid' },
  dmc: { n: 'Dimethyl Carbonate', c: '#e0e8f0', f: '(CH₃O)₂CO. A mild, low-toxicity solvent that carries a carbonate group without the need for phosgene', cp: 1.6, t: 40 },
  dpc: { n: 'Diphenyl Carbonate', c: '#e8e4f0', f: '(C₆H₅O)₂CO, kept molten above its 80°C melting point', cp: 1.5, t: 100 },
