  cobble_path: { n: 'Cobbled Lane', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#a09a8c', pv: ['cobble', '#a09a8c', '#7a7468'], cost: { sett: 2, sand: 1 }, makes: 2, d: 'Rounded setts bedded in sand, worn smooth on top. Walking on it is a little quicker. Drag to lay a line.' },
