  stretcher_path: { n: 'Stretcher Bond Paving', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#b8603e', pv: ['stretcher', '#b8603e', '#6a5040'], cost: { face_brick: 2 }, makes: 2, d: 'Bricks laid end to end in staggered rows. Walking on it is a little quicker. Drag to lay a line.' },
