  blue_brick_path: { n: 'Blue Engineering Brick', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#3a3e4a', pv: ['stretcher', '#3a3e4a', '#22242a'], cost: { face_brick: 2, coke: 1 }, makes: 2, d: 'Bricks fired in a reducing atmosphere until the iron turns dark blue-black. Walking on it is a little quicker. Drag to lay a line.' },
