  mosaic_path: { n: 'Mosaic', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#d8d0c0', pv: ['mosaic', '#d8d0c0', '#2a5ab0|#d8a030|#c03a3a|#f0ece0|#3a8a5a|#1e2a4a'], cost: { floor_tile: 1, glass: 1 }, makes: 2, d: 'Small glass and ceramic squares set by hand. Walking on it is a little quicker. Drag to lay a line.' },
