  resin_path: { n: 'Resin-Bound Gravel', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#c8a868', pv: ['speck', '#c8a868', '#e8d0a0|#8a6a40|#f0e4c8|#6a5030', '#8a7a5a'], cost: { gravel: 2, epoxy: 1 }, makes: 3, d: 'Gravel glued with clear resin. Smooth, porous and weed free. Walking on it is a little quicker. Drag to lay a line.' },
  red_asphalt: { n: 'Red Asphalt', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#8a3a2e', pv: ['smooth', '#8a3a2e', '#7a3026'], cost: { asphalt: 1, iron_red: 1 }, makes: 3, d: 'Asphalt pigmented with iron oxide. Walking on it is a little quicker. Drag to lay a line.' },
  cycle_lane: { n: 'Green Cycle Lane', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#3a7a4a', pv: ['smooth', '#3a7a4a', '#2e6a3e', 'lane'], cost: { asphalt: 1, chrome_green: 1 }, makes: 3, d: 'Coloured asphalt with a white dashed centre line. Walking on it is a little quicker. Drag to lay a line.' },
