  bark_path: { n: 'Bark Mulch Trail', kind: 'road', w: 1, h: 1, cat: 'Decor', c: '#5a3a24', pv: ['bark', '#5a3a24', '#8a5a34|#6a4428|#a87a4a|#3a2618'], cost: { wood_chips: 2 }, makes: 4, d: 'Shredded bark laid thick. Soft underfoot. Walking on it is a little quicker. Drag to lay a line.' },
