  glazed_wall: { n: 'Glazed Brick Wall', kind: 'wall', w: 1, h: 1, cat: 'Decor', c: '#2a6a9a', wv: ['brick', '#2a6a9a', '#e0e0d8'], cost: { face_brick: 3, glaze: 1 }, makes: 2, hp: 800, d: 'Bricks dipped in blue glaze before firing. Joins up with neighbouring walls and fences. Crawlers must chew through it.' },
  glassblock_wall: { n: 'Glass Block Wall', kind: 'wall', w: 1, h: 1, cat: 'Decor', c: '#b8d8e0', wv: ['glass', '#b8d8e0', '#8a9898'], cost: { glass: 3 }, makes: 2, hp: 500, d: 'Hollow pressed glass blocks that let the light through. Joins up with neighbouring walls and fences. Crawlers must chew through it.' },
