  palisade_fence: { n: 'Steel Palisade', kind: 'wall', w: 1, h: 1, cat: 'Decor', c: '#3a5a3a', wv: ['palisade', '#3a5a3a', '#22362a'], cost: { galv_steel: 2 }, makes: 2, hp: 1000, d: 'Pointed steel pales, galvanised and powder-coated green. Joins up with neighbouring walls and fences. Crawlers must chew through it.' },
