  gabion_wall: { n: 'Gabion Wall', kind: 'wall', w: 1, h: 1, cat: 'Decor', c: '#b0a890', wv: ['gabion', '#b0a890', '#c8ccd0'], cost: { galv_steel: 1, limestone: 3 }, makes: 2, hp: 1600, d: 'Wire baskets packed with stone. Joins up with neighbouring walls and fences. Crawlers must chew through it.' },
